import React, { useRef } from 'react';
import './ImageLinkForm.css';

const ImageLinkForm = ({ onInputChange, onButtononSubmit, onFileChange }) => {
	const fileInputRef = useRef(null);

	const handleBrowseClick = () => {
		fileInputRef.current.click();
	};

	return (
		<div>
			<p className='f3'>
				{'This Magic Brain will detect faces in your pictures. Give it a Try'}
			</p>

			<div className='center'>
				<div className='form center pa4 br3 shadow-5'>
					<input className='f4 pa2 w-60 center' type='text' placeholder='Paste image URL here...' onChange={onInputChange} />
					<button
						className='w-20 grow f4 link ph3 pv2 dib white bg-light-purple'
						onClick={onButtononSubmit}
					>Detect</button>
					<button
						className='w-20 grow f4 link ph3 pv2 dib white bg-dark-green ml1 browse-btn'
						onClick={handleBrowseClick}
					>Browse</button>
					<input
						ref={fileInputRef}
						type='file'
						accept='image/*'
						style={{ display: 'none' }}
						onChange={onFileChange}
					/>
				</div>
			</div>
		</div>
	);
}

export default ImageLinkForm;
